<script lang="ts">import {createSelectController} from "@civaria/core";import {normalizeSvelteProps} from "./internal.js";type Item={value:string;label?:string;disabled?:boolean};let {items=[],value=$bindable(""),placeholder="Select…",name,required=false,disabled=false,id="civ-select"}=$props<{items?:Item[];value?:string;placeholder?:string;name?:string;required?:boolean;disabled?:boolean;id?:string}>();const controller=createSelectController({id,defaultValue:value,onValueChange:next=>value=next});controller.setItems(items);let state=$state(controller.getState());$effect(()=>{const off=controller.subscribe(next=>state=next);return off});$effect(()=>{controller.setItems(items);if(value!==state.value)controller.syncValue(value)});function p(kind:"root"|"trigger"|"content"|"item"|"hiddenInput",index=0){state;if(kind==="root")return normalizeSvelteProps(controller.getRootProps());if(kind==="trigger"){const out=normalizeSvelteProps(controller.getTriggerProps());return {...out,disabled:disabled||undefined,"aria-required":required||undefined}}if(kind==="content")return normalizeSvelteProps(controller.getContentProps());if(kind==="hiddenInput")return normalizeSvelteProps(controller.getHiddenInputProps(name,required,disabled));return normalizeSvelteProps(controller.getItemProps(index))}let selected=$derived(items.find(item=>item.value===state.value));</script><div {...p("root")} class="civ-select"><button {...p("trigger")} class="civ-select__trigger">{selected?.label??placeholder}</button><div {...p("content")} class="civ-select__content">{#each items as item,index (item.value)}<div {...p("item",index)} class="civ-select__item">{item.label??item.value}</div>{/each}</div><input {...p("hiddenInput")} class="civ-select__hiddenInput" /></div>
